function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function avgAttendance(s){let a=0,t=0;subjects.forEach(k=>{a+=s.attended[k];t+=s.held[k]});return t?a/t*100:0}
function statusFor(p){return p<75?"red":p===75?"yellow":"green"}
function pill(text,kind){return `<span class="pill ${kind}">${text}</span>`}
function initials(name){return name.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase()}
function scorePill(score){return pill(score>=80?"Low risk":score>=65?"Monitor":"High risk",score>=80?"green":score>=65?"yellow":"red")}
function header(title,desc,button=""){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
function stat(label,value,note,icon){return `<div class="card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function progress(p,kind=""){return `<div class="progress ${kind}"><span style="width:${Math.max(0,Math.min(100,p))}%"></span></div>`}
function subjectOverall(s){return avgAttendance(s)}
