function renderExamDatesheet(){content.innerHTML=header('Examination · Datesheet','Add exam date, time, venue and maximum marks. Saved rows are visible in this faculty workspace.',`<span class="pill purple">Faculty workspace</span>`)+`<div class="grid two-col"><section class="card"><h2 class="section-title">Upload / add exam datesheet</h2><form id="datesheetForm"><div class="field"><label>Exam title</label><input id="examTitle" required placeholder="e.g. Modern C Programming · End-Semester"></div><div class="field-row"><div class="field"><label>Course</label><select id="examCourse">${courses.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Exam type</label><select id="examType"><option>Written exam</option><option>Practical</option><option>Viva</option><option>Internal assessment</option></select></div></div><div class="field-row"><div class="field"><label>Date</label><input id="examDate" type="date" required></div><div class="field"><label>Start time</label><input id="examTime" type="time" required></div></div><div class="field-row"><div class="field"><label>Room / venue</label><input id="examVenue" required placeholder="Lecture Hall 301"></div><div class="field"><label>Maximum marks</label><input id="examMaxMarks" type="number" min="1" value="50" required></div></div><button class="btn" type="submit">Save exam date</button></form><p class="muted" style="font-size:11px;margin-top:12px">Demo saves remain in this browser session. Connect the college exam system to publish a live datesheet.</p></section><section class="card"><h2 class="section-title">Datesheet entries (${examDatesheet.length})</h2><div class="table-wrap"><table><thead><tr><th>Exam / course</th><th>Date</th><th>Time</th><th>Venue</th><th>Marks</th></tr></thead><tbody>${examDatesheet.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<tr><td><strong>${esc(e.title)}</strong><br><span class="muted">${esc(e.type)} · ${esc(e.course)}</span></td><td>${new Date(e.date+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}</td><td>${esc(e.time)}</td><td>${esc(e.venue)}</td><td>${e.maxMarks}</td></tr>`).join('')}</tbody></table></div></section></div>`;document.getElementById('datesheetForm').addEventListener('submit',e=>{e.preventDefault();examDatesheet.push({id:'EX-'+Date.now(),title:document.getElementById('examTitle').value.trim(),course:document.getElementById('examCourse').value,type:document.getElementById('examType').value,date:document.getElementById('examDate').value,time:document.getElementById('examTime').value,venue:document.getElementById('examVenue').value.trim(),maxMarks:Number(document.getElementById('examMaxMarks').value)});toast('Exam date saved in this demo.');renderExamDatesheet()})}
function renderExamMarks(){if(!examDatesheet.length){content.innerHTML=header('Examination · Marks Update','Select an exam and enter marks for each student.');return}const examId=document.getElementById('marksExamSelect')?.value||examDatesheet[0].id,exam=examDatesheet.find(x=>x.id===examId)||examDatesheet[0];content.innerHTML=header('Examination · Marks Update','Enter and save each student’s marks for the selected exam.',`<span class="pill purple">Faculty only</span>`)+`<section class="card"><div class="toolbar"><label for="marksExamSelect"><strong>Exam</strong></label><select id="marksExamSelect">${examDatesheet.map(x=>`<option value="${x.id}" ${x.id===exam.id?'selected':''}>${esc(x.title)} · max ${x.maxMarks}</option>`).join('')}</select>${pill('Maximum: '+exam.maxMarks+' marks','blue')}</div><div class="table-wrap"><table><thead><tr><th>Student</th><th>UID / section</th><th>Attendance</th><th>Marks (0–${exam.maxMarks})</th></tr></thead><tbody>${students.map(st=>{const key=exam.id+'_'+st.uid;return `<tr><td><strong>${esc(st.name)}</strong></td><td>${st.uid} · ${esc(st.section)}</td><td>${avgAttendance(st).toFixed(0)}%</td><td><input data-mark-uid="${st.uid}" type="number" min="0" max="${exam.maxMarks}" value="${examMarks[key]??''}" placeholder="Enter marks" style="width:130px;padding:8px;border:1px solid var(--line);border-radius:7px"></td></tr>`}).join('')}</tbody></table></div><div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="btn" onclick="saveExamMarks('${exam.id}',${exam.maxMarks})">Save marks</button></div><p class="muted" style="font-size:11px;margin-top:12px">Marks are stored in this demo page session only. Verify scores before transferring them to the official record system.</p></section>`;document.getElementById('marksExamSelect').addEventListener('change',e=>{selectedExamId=e.target.value;renderExamMarks()})}
let selectedExamId='';
function saveExamMarks(examId,max){let errors=0;document.querySelectorAll('[data-mark-uid]').forEach(inp=>{const value=inp.value.trim();if(value==='')return;const n=Number(value);if(!Number.isFinite(n)||n<0||n>max){errors++;return}examMarks[examId+'_'+inp.dataset.markUid]=n});if(errors){toast('Some marks are outside the allowed range.');return}toast('Student marks saved in this demo.');renderExamMarks()}
function renderExamAssignments(){content.innerHTML=header('Examination · Assignments','Publish assignment questions with a due date and review student submissions in the same workspace.',`<span class="pill purple">Faculty assignment desk</span>`)+`<div class="grid two-col"><section class="card"><h2 class="section-title">Create assignment</h2><form id="examAssignmentForm"><div class="field"><label>Assignment title</label><input id="newAssignmentTitle" required placeholder="Assignment title"></div><div class="field"><label>Course</label><select id="newAssignmentCourse">${courses.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Question / instructions</label><textarea id="newAssignmentQuestion" required placeholder="Write the question and submission instructions"></textarea></div><div class="field-row"><div class="field"><label>Submit by (due date)</label><input id="newAssignmentDue" type="date" required></div><div class="field"><label>Maximum marks</label><input id="newAssignmentMax" type="number" min="1" value="20" required></div></div><button class="btn" type="submit">Publish assignment</button></form></section><section class="card"><h2 class="section-title">Published assignments</h2>${examAssignments.map(a=>{const count=assignmentSubmissions.filter(x=>x.assignmentId===a.id).length;return `<details style="padding:12px 0;border-bottom:1px solid var(--line)"><summary style="cursor:pointer;font-weight:750">${esc(a.title)} · due ${esc(a.due)} ${pill(count+' submitted','blue')}</summary><p class="muted" style="font-size:13px;white-space:pre-wrap">${esc(a.question)}</p><p class="muted" style="font-size:12px">${esc(a.course)} · Max ${a.maxMarks} marks</p></details>`}).join('')}</section></div><section class="card" style="margin-top:16px"><div class="split"><h2 class="section-title">Student submission portal · preview</h2>${pill('Demo student view','yellow')}</div><p class="muted" style="font-size:12px">This preview shows where students would submit. In this prototype, choose a sample student; real student accounts and file storage need a secure backend.</p><form id="studentAssignmentForm"><div class="field-row"><div class="field"><label>Assignment</label><select id="submitAssignment">${examAssignments.map(a=>`<option value="${a.id}">${esc(a.title)} · due ${esc(a.due)}</option>`).join('')}</select></div><div class="field"><label>Student (demo)</label><select id="submitStudent">${students.map(st=>`<option value="${st.uid}">${esc(st.name)} · ${st.uid}</option>`).join('')}</select></div></div><div class="field"><label>Student answer / notes</label><textarea id="studentAnswer" placeholder="Type an answer or add a note for the faculty"></textarea></div><div class="field"><label>Attach file (demo preview)</label><input id="studentFile" type="file" accept=".pdf,.doc,.docx,.txt,.c,.cpp"></div><button class="btn" type="submit">Submit assignment</button></form><h3 style="font-size:15px;margin:22px 0 10px">Received submissions (${assignmentSubmissions.length})</h3><div class="table-wrap"><table><thead><tr><th>Student</th><th>Assignment</th><th>Submitted at</th><th>Answer / attachment</th></tr></thead><tbody>${assignmentSubmissions.map(sub=>{const st=students.find(x=>x.uid===sub.uid),as=examAssignments.find(x=>x.id===sub.assignmentId);return `<tr><td>${esc(st?.name||sub.uid)} · ${sub.uid}</td><td>${esc(as?.title||'Assignment')}</td><td>${esc(sub.submittedAt)}</td><td>${esc(sub.answer||'—')} ${sub.fileName?' · '+esc(sub.fileName):''}</td></tr>`}).join('')}</tbody></table></div></section>`;document.getElementById('examAssignmentForm').addEventListener('submit',e=>{e.preventDefault();examAssignments.push({id:'EA-'+Date.now(),title:document.getElementById('newAssignmentTitle').value.trim(),course:document.getElementById('newAssignmentCourse').value,question:document.getElementById('newAssignmentQuestion').value.trim(),due:document.getElementById('newAssignmentDue').value,maxMarks:Number(document.getElementById('newAssignmentMax').value)});toast('Assignment published in this demo.');renderExamAssignments()});document.getElementById('studentAssignmentForm').addEventListener('submit',e=>{e.preventDefault();const file=document.getElementById('studentFile').files[0];assignmentSubmissions.push({assignmentId:document.getElementById('submitAssignment').value,uid:document.getElementById('submitStudent').value,answer:document.getElementById('studentAnswer').value.trim(),fileName:file?.name||'',submittedAt:new Date().toLocaleString()});toast('Demo submission received.');renderExamAssignments()})}
function renderPaperBuilder(){content.innerHTML=header('Examination · Question Paper Builder','Prepare and save exam papers. Saved drafts stay in the faculty-only workspace.',`${pill('Faculty only · hidden from student pages','purple')}`)+`<div class="grid two-col"><section class="card"><h2 class="section-title">Create question paper</h2><form id="paperForm"><div class="field"><label>Paper title</label><input id="paperTitle" required placeholder="e.g. Modern C Programming · Mid-Semester"></div><div class="field-row"><div class="field"><label>Course</label><select id="paperCourse">${courses.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Exam</label><select id="paperExam">${examDatesheet.map(e=>`<option>${esc(e.title)}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label>Duration</label><input id="paperDuration" required placeholder="e.g. 2 hours"></div><div class="field"><label>Total marks</label><input id="paperMarks" type="number" min="1" value="50" required></div></div><div class="field"><label>Questions (one per line)</label><textarea id="paperQuestions" required placeholder="1. Explain pointers in C. (5 marks)&#10;2. Write a program using arrays. (10 marks)"></textarea></div><button class="btn" type="submit">Save faculty-only paper</button></form></section><section class="card"><div class="split"><h2 class="section-title">Saved papers (${savedPapers.length})</h2>${pill('Faculty only','purple')}</div><p class="muted" style="font-size:12px">This private list is rendered only inside the Faculty / Admin Examination workspace; no student-facing page displays saved papers.</p>${savedPapers.length?savedPapers.map(p=>`<details style="padding:12px 0;border-bottom:1px solid var(--line)"><summary style="cursor:pointer;font-weight:750">${esc(p.title)} · ${pill('Private draft','purple')}</summary><p class="muted" style="font-size:12px">${esc(p.course)} · ${esc(p.exam)} · ${esc(p.duration)} · ${p.total} marks · Saved ${esc(p.savedAt)}</p><pre style="white-space:pre-wrap;font:inherit;font-size:13px">${esc(p.questions)}</pre></details>`).join(''):`<div class="empty">No papers saved yet. Your saved papers will appear here for faculty review.</div>`}</section></div><p class="muted" style="font-size:11px;margin-top:14px">Local prototype: saved drafts exist in this browser session. A real system should enforce faculty-only access on the server as well.</p>`;document.getElementById('paperForm').addEventListener('submit',e=>{e.preventDefault();savedPapers.unshift({title:document.getElementById('paperTitle').value.trim(),course:document.getElementById('paperCourse').value,exam:document.getElementById('paperExam').value,duration:document.getElementById('paperDuration').value.trim(),total:Number(document.getElementById('paperMarks').value),questions:document.getElementById('paperQuestions').value.trim(),savedAt:new Date().toLocaleString()});toast('Question paper saved privately in this demo.');renderPaperBuilder()})}
function renderTimetable(){const days=['Monday','Tuesday','Wednesday','Thursday','Friday'],today=teacherSchedule.filter(x=>x.day===selectedDay);content.innerHTML=header('Rajat Gupta · Teacher Timetable','Modern C Programming · Select a day to view assigned classes, lecture / lab sessions and rooms.',`<button class="btn secondary" onclick="window.print()">Print timetable</button>`)+`<div class="grid stats">${stat('Teacher','Rajat Gupta','Modern C Programming','♙')}${stat('Classes today',today.length,'Assigned lectures and labs','▤')}${stat('Labs today',today.filter(x=>x.session.includes('Lab')).length,'Practical sessions','⌘')}${stat('Selected day',selectedDay,'Weekly teaching schedule','→')}</div><div class="tab-row day-tabs">${days.map(d=>`<button class="tab ${selectedDay===d?'active':''}" onclick="setTimetableDay('${d}')">${d}</button>`).join('')}</div><section class="card"><div class="split"><div><h2 class="section-title" style="margin-bottom:4px">${selectedDay} · Modern C Programming</h2><span class="muted" style="font-size:12px">Teacher: Rajat Gupta</span></div>${pill(today.length+' sessions','blue')}</div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Lecture / lab</th><th>Class / section</th><th>Room</th><th>Topic to teach</th></tr></thead><tbody>${today.map(x=>`<tr><td><strong>${x.time}</strong></td><td>${x.session}</td><td>${x.group}</td><td>${x.hall}</td><td>${x.topic}</td></tr>`).join('')}</tbody></table></div><p class="muted" style="font-size:11px;margin-top:12px">Combined Group A + Group B rows are joint lab sessions. Verify the listed class times against the official timetable.</p></section>`}
function setTimetableDay(d){selectedDay=d;renderTimetable()}
function renderAcademicCalendar(){content.innerHTML=header('Academic Calendar','Full academic session · July 2026 to May 2027. Dates are illustrative and can be updated to match your college calendar.',`<button class="btn secondary small" onclick="downloadCalendarPDF()">↓ Download PDF</button>`)+`<div class="grid stats">${stat('Academic session','2026–27','July 2026 – May 2027','▦')}${stat('Calendar months',academicCalendar.length,'Full session overview','◷')}${stat('Key dates',academicCalendar.reduce((n,m)=>n+m.events.length,0),'Exams, classes and reviews','✓')}${stat('Next milestone','13 Jul 2026','Semester classes begin','→')}</div><div class="grid three-col academic-months">${academicCalendar.map(m=>`<section class="card"><h2 class="section-title">${m.month}</h2>${m.events.map(([d,t])=>`<div class="notice"><div class="notice-icon">▦</div><div><strong>${d}</strong><p>${t}</p></div></div>`).join('')}</section>`).join('')}</div><p class="muted" style="font-size:11px;margin-top:16px">Calendar dates shown are sample planning dates, not official university notices.</p>`}
function downloadCalendarPDF(){const lines=['FACULYTICS - ACADEMIC CALENDAR','Academic Session 2026-27 | July 2026 to May 2027','Sample planning dates - confirm against official college notices',''];academicCalendar.forEach(m=>{lines.push(m.month.toUpperCase());m.events.forEach(([d,t])=>lines.push('  '+d+'  '+t));lines.push('')});const escPdf=t=>t.replace(/[^\x20-\x7E]/g,'').replace(/([\\()])/g,'\\$1');const stream='BT /F1 10 Tf 50 790 Td 15 TL '+lines.map((x,i)=>`(${escPdf(x)}) Tj T*`).join(' ')+' ET';const objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${new TextEncoder().encode(stream).length} >>\nstream\n${stream}\nendstream`];let pdf='%PDF-1.4\n',offsets=[0];objs.forEach((o,i)=>{offsets.push(new TextEncoder().encode(pdf).length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`});const xref=new TextEncoder().encode(pdf).length;pdf+=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objs.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'}));a.href=url;a.download='academic-calendar-2026-27.pdf';a.click();URL.revokeObjectURL(url);toast('Academic calendar PDF downloaded.')}

function setAttendanceView(v){attendanceView=v;renderAttendance();if(v==="rectification")setTimeout(()=>document.getElementById("rectificationSection")?.scrollIntoView({behavior:"smooth"}),50)}
function openAccount(tab){accountTab=tab;page="account";document.getElementById("accountPop")?.classList.remove("show");document.querySelectorAll(".nav-group").forEach(g=>g.classList.toggle("open",g.id==="facultyNavGroup"));render()}
function renderAccount(){
 const tabs=[['profile','Faculty profile'],['password','Change password'],['email','Email'],['settings','Settings']];
 let body='';
 if(accountTab==='profile')body=`<div class="student-header"><div class="student-avatar">FA</div><div><h2>Rajat Gupta</h2><p class="muted" style="margin:0">Faculty ID: FACULTY01 · Demo account</p></div></div><div class="field-row"><div class="field"><label>Full name</label><input value="Rajat Gupta" id="facultyName"></div><div class="field"><label>Faculty UID</label><input value="FACULTY01" disabled></div></div><div class="field"><label>Department</label><input value="Computer Science & Engineering"></div><div class="field"><label>Designation</label><input value="Faculty / Admin"></div><button class="btn" onclick="toast('Profile changes saved in this demo only.')">Save profile</button>`;
 if(accountTab==='password')body=`<p class="muted">Set a new password for this demo interface. A real system must validate this securely on a server.</p><div class="field"><label>Current password</label><input id="oldPassword" type="password" placeholder="Current password"></div><div class="field"><label>New password</label><input id="newPassword" type="password" minlength="8" placeholder="At least 8 characters"></div><div class="field"><label>Confirm new password</label><input id="confirmPassword" type="password" minlength="8" placeholder="Repeat new password"></div><button class="btn" onclick="changeDemoPassword()">Update password</button>`;
 if(accountTab==='email')body=`<p class="muted">Manage the email address used for faculty notifications in this prototype.</p><div class="field"><label>Faculty email</label><input id="facultyEmail" type="email" value="faculty@alphadynamic.edu" placeholder="name@college.edu"></div><label style="display:flex;gap:9px;align-items:center;font-size:13px;margin:12px 0"><input type="checkbox" checked> Receive attendance and student-risk notifications</label><label style="display:flex;gap:9px;align-items:center;font-size:13px;margin:12px 0"><input type="checkbox" checked> Receive student query notifications</label><button class="btn" onclick="toast('Email preferences saved in this demo only.')">Save email settings</button>`;
 if(accountTab==='settings')body=`<div class="settings-row"><div><strong>Theme</strong><div class="muted" style="font-size:12px;margin-top:4px">Switch the workspace appearance</div></div><div class="theme-options"><button class="tab ${document.body.classList.contains('dark-mode')?'':'active'}" onclick="applyTheme('light')">☀ Light</button><button class="tab ${document.body.classList.contains('dark-mode')?'active':''}" onclick="applyTheme('dark')">☾ Dark</button></div></div><div class="settings-row"><div><strong>Dashboard colour</strong><div class="muted" style="font-size:12px;margin-top:4px">Choose a colour accent for the portal</div></div><select id="accentChoice" onchange="applyAccent(this.value)"><option value="blue">Ocean blue</option><option value="purple">Violet</option><option value="teal">Teal</option><option value="coral">Coral</option></select></div><div class="settings-row"><div><strong>Compact tables</strong><div class="muted" style="font-size:12px;margin-top:4px">Reduce table cell spacing</div></div><input type="checkbox" onchange="document.querySelectorAll('th,td').forEach(x=>x.style.padding=this.checked?'8px 10px':'13px 14px')"></div><div class="settings-row"><div><strong>Data & privacy</strong><div class="muted" style="font-size:12px;margin-top:4px">This prototype uses illustrative sample records.</div></div><span class="pill yellow">Demo mode</span></div><button class="btn secondary" onclick="toast('Settings are applied locally in this browser session.')">Save settings</button>`;
 content.innerHTML=header('Faculty / Admin','Manage faculty account, profile, email and portal preferences.')+`<div class="grid two-col account-panel"><section class="card"><h2 class="section-title">Account</h2><div class="tab-row">${tabs.map(([id,label])=>`<button class="tab ${accountTab===id?'active':''}" onclick="openAccount('${id}')">${label}</button>`).join('')}</div></section><section class="card"><h2 class="section-title">${tabs.find(x=>x[0]===accountTab)[1]}</h2>${body}</section></div>`;
}
function changeDemoPassword(){const old=document.getElementById('oldPassword').value,n=document.getElementById('newPassword').value,c=document.getElementById('confirmPassword').value;if(old!==demoPassword){toast('Current password is incorrect.');return}if(n.length<8){toast('Use at least 8 characters.');return}if(n!==c){toast('New passwords do not match.');return}demoPassword=n;toast('Demo password changed for this page session.')}
function applyTheme(v){document.body.classList.toggle('dark-mode',v==='dark');if(page==='account'&&accountTab==='settings')renderAccount();toast((v==='dark'?'Dark':'Light')+' theme applied.') }
function applyAccent(v){const palettes={blue:['#2674d9','#eaf3ff','#17345f'],purple:['#7c3aed','#f1eafe','#402070'],teal:['#0f9b8e','#e0f7f4','#124e4a'],coral:['#e45c6f','#fff0f2','#71303a']};const a=palettes[v]||palettes.blue;document.documentElement.style.setProperty('--blue',a[0]);document.documentElement.style.setProperty('--blue-soft',a[1]);document.documentElement.style.setProperty('--navy',a[2]);toast('Colour theme updated.')}
function logout(){document.body.classList.add('login-active');document.getElementById('loginScreen').style.display='grid';document.getElementById('teacherPassword').value='';document.getElementById('captchaInput').value='';document.getElementById('accountPop')?.classList.remove('show');refreshCaptcha();toast('You have been logged out.')}
function showModal(title,body,onSave){
 document.getElementById("modalRoot").innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal"><h2>${title}</h2><p>Review the information before confirming.</p>${body}<div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn" id="modalSave">Save changes</button></div></section></div>`;
 document.getElementById("modalSave").onclick=()=>{onSave();closeModal()};
}
function closeModal(){document.getElementById("modalRoot").innerHTML=""}
function toast(msg){const root=document.getElementById("toastRoot");root.innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>root.innerHTML="",2800)}
function exportCSV(){
 const rows=[["UID","Name","Section","Attendance %","Marks %","Success Score","Rank","CGPA","Syllabus %","Quizzes done","Quizzes total","Assignments submitted","Assignments total"],...students.map(s=>[s.uid,s.name,s.section,avgAttendance(s).toFixed(2),s.marks,s.score,s.rank,s.cgpa,s.syllabus,s.quizzesDone,s.quizzesTotal,s.assignmentsDone,s.assignmentsTotal])];
 const csv=rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(",")).join("\r\n");
 const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="faculytics-student-reports-demo.csv";a.click();URL.revokeObjectURL(url);toast("Student report CSV exported.");
}
let captchaValue="A7K4P", demoPassword="Alpha@123";
function refreshCaptcha(){const chars="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";captchaValue=Array.from({length:5},()=>chars[Math.floor(Math.random()*chars.length)]).join("");document.getElementById("captchaCode").textContent=captchaValue;}
document.getElementById("refreshCaptcha").addEventListener("click",refreshCaptcha);

document.getElementById("loginForm").addEventListener("submit",e=>{e.preventDefault();const uid=document.getElementById("teacherUid").value.trim(),pw=document.getElementById("teacherPassword").value,cap=document.getElementById("captchaInput").value.trim().toUpperCase(),err=document.getElementById("loginError");if(uid.toUpperCase()==="FACULTY01"&&pw===demoPassword&&cap===captchaValue){document.body.classList.remove("login-active");document.getElementById("loginScreen").style.display="none";toast("Signed in to FACULYTICS demo.");}else{err.style.display="block";err.textContent=cap!==captchaValue?"Captcha incorrect. Please try again.":"Teacher UID or password is incorrect.";refreshCaptcha();document.getElementById("captchaInput").value="";}});
document.getElementById("forgotPassword").addEventListener("click",()=>{const err=document.getElementById("loginError");err.style.display="block";err.textContent="For this demo, contact your college administrator to reset the teacher password. Password reset is not connected to a real account system.";});
document.getElementById("nav").addEventListener("click",e=>{const toggle=e.target.closest("button[data-toggle]");if(toggle){document.getElementById(toggle.dataset.toggle).classList.toggle('open');return}const logoutBtn=e.target.closest("button[data-action=logout]");if(logoutBtn){logout();return}const b=e.target.closest("button[data-page]");if(b){page=b.dataset.page;currentSearch="";if(b.dataset.lmsTab)lmsTab=b.dataset.lmsTab;if(b.dataset.attView){attendanceView=b.dataset.attView;if(b.dataset.subject)selectedAttendanceSubject=b.dataset.subject;else if(attendanceView!=='subject')selectedAttendanceSubject='all'}if(b.dataset.accountTab)accountTab=b.dataset.accountTab;render();if(page==='attendance'&&attendanceView==='subject'){const sel=document.getElementById('attSubject');if(sel)sel.value=selectedAttendanceSubject;sel?.dispatchEvent(new Event('change'))}return}});
document.getElementById('profileMenuBtn').addEventListener('click',()=>document.getElementById('accountPop').classList.toggle('show'));
document.addEventListener('click',e=>{if(!e.target.closest('.account-menu'))document.getElementById('accountPop')?.classList.remove('show')});
document.getElementById("globalSearch").addEventListener("input",e=>{currentSearch=e.target.value;if(page==="reports")renderReports();else if(page==="attendance")renderAttendance();else{page="reports";render() }});
document.getElementById("helpTop").addEventListener("click",()=>{page="support";render()});
render();
